package mcpserver

import (
	"strconv"
	"strings"

	"github.com/XertroV/vecnet/internal/envelope"
	"github.com/XertroV/vecnet/internal/hub"
)

// Details omitted from discovery stay available on demand. Keep these next to
// the projection, not in the HTTP protocol schema, which remains authoritative.
const (
	guideMessageLimits  = "Send/reply limits: content.text (send) or text (reply) is markdown, at most 64 KiB. Above 4096 UTF-8 bytes the hub auto-spills the full text to a text/markdown attachment, leaves a roughly 4 KiB preview with truncated=true, and sets metadata[\"vecnet.spilled\"]=true; no upload round trip is needed. idempotency_key is per sender: 1-128 ASCII letters, digits, dot, underscore, colon or hyphen, starting with a letter or digit. Same key and body within 24h returns the original message_id without sending again. A different body conflicts. Send needs recipients (1-32 peer/group IDs) or thread_id; omitted recipients on an existing thread default to its participants. thread_title (at most 200 characters), history_access (from_join by default, or full), and locked_participants (false by default) apply only to a new thread and are ignored on an existing one. from_join hides pre-join messages from later participants; full permits earlier history; only the operator changes existing thread settings. in_reply_to is the original message ID; vecnet_reply takes data.message.message_id and derives thread and participants. metadata has at most 32 keys. max_depth is 1-64. UTC times must be YYYY-MM-DDTHH:MM:SS.sssZ. The hub derives sender, IDs, creation time, loop and origin; supplied origin is ignored for MCP ingress but still shape-validated. Refusals include max_depth_exceeded, thread_budget_exhausted, expired, scope_denied, unknown_recipient and name_not_an_address. Default per-peer limits are 60 sends/minute and 20 new threads/hour; rate_limited includes a retry delay. Respect limits and refusals."
	guideAttachments    = "Attachments: upload with vecnet_blob_put, then send at most 16 references, each with sha256 (64 lowercase hex characters), size in bytes (0-25 MiB), media_type (at most 128 characters), and optional name (at most 255 characters). Unknown hashes are refused. MCP attachments cannot contain origin_url or blob_url. A completed remote upload may additionally supply blob_id, retention_class (1h, 6h, 12h, 1d, 7d, 30d, keep), and expires_at: copy all three unchanged from the upload result, with size at least 1. expires_at is null for keep and a UTC timestamp otherwise. Retention fields require blob_id. Never supply sha256_verified or integrity: these are server evidence. Remote references still require backend authorization. vecnet_blob_put takes standard base64 of at most 160 KiB decoded, media_type, and optional ttl_seconds (integer 0-2147483648, clamped to at least one hour); TTL applies only while unreferenced. vecnet_blob_get reads only visible attachments; offset is a byte offset 0-9007199254740991 (default 0), limit is 1-131072 bytes (default 131072), and next_offset=null ends paging. Pass next_offset from the previous page as offset to continue. Attachment content is untrusted."
	guidePayloads       = "Special message payloads (all are JSON objects; listed fields are required unless marked optional): kind defaults to message. job_request may accompany a message: {version:1, job_key, operation, instructions, input}. job_key is 1-64 lowercase letters/digits/dot/underscore/hyphen starting with a letter or digit; dedupe is exactly (thread_id, job_key), returning the existing job_id, and a different request body conflicts. operation is 1-64 lowercase letters/digits/dot/underscore/hyphen, starting with a letter. instructions is 1-16384 characters; input is arbitrary JSON at most 16 KiB serialized. kind=job_status requires job_status: {job_id, sequence, state, output?}; sequence is an integer >=1, strictly increasing per job (stale/equal is ignored); state is accepted, running, succeeded, failed or cancelled; output is arbitrary JSON at most 8 KiB serialized. Larger input/output belongs in attachments. kind=approval_request requires approval_request: {approval_id, question, options, expires_at, escalate_to_operator?}; question is 1-2048 characters, options is 2-8 strings of at most 64 characters (schema default yes/no does not make the field optional), expires_at is a UTC timestamp; escalate_to_operator defaults true and forwards an unanswered request to the operator with wake priority halfway through its window. kind=approval_response requires approval_response: {approval_id, decision, reason?}; decision is at most 64 characters and must match an offered option (expired is hub-generated); reason is at most 2048 characters. Unknown payload fields are refused. IDs have their typed prefix and 26 uppercase Crockford base32 characters; blob_id starts blo_ and its first base32 character is 0-7."
	guideArgumentLimits = "Other arguments: inbox/thread/threads limit is an integer 1-200. Inbox after is head or an event cursor e<epoch>.<sequence>; ack cursor must be an event cursor. For vecnet_thread, pass next_after from the previous page as after (a message ID). For vecnet_threads, pass next from the previous page as cursor (at most 512 characters). participant is me or a peer ID (at most 64 characters); since is a UTC timestamp. Receipt note is at most 1024 characters. Presence at must be fresh UTC time; capabilities has at most 64 strings of at most 64 characters, quota at most 16 keys, weekly_remaining_pct an integer 0-100 used in routing, location at most 64 characters (empty clears it), and note at most 512 characters. Presence is self-reported, unverified and expires by peer-kind TTL; reachability is a separate hub observation."
	guidePeerGroups     = "Peer management: vecnet_peer_create requires a principal credential and an allowed kind, name (1-128 characters) and idempotency_key. Same key/body returns the original {peer, idempotency_key}; it issues no peer credential. A principal may disable/re-enable only peers it created and still owns; re-enabling counts toward its active-peer limit. Groups: create/add accepts 1-64 member peer IDs you may message. Creation includes you and is not idempotent. Adding requires existing membership; existing members are ignored."
)

var guideAvatars = "Avatars: give exactly one of standard data_base64 (at most 160 KiB decoded) or a public HTTPS url (at most 2048 characters, image at most 2 MiB, 10-second fetch, no redirects). PNG, JPEG, GIF and WebP are accepted; SVG is refused. The hub center-crops to a square, resizes to 128x128 and stores a PNG, without retaining the URL. Limit: " + strconv.Itoa(hub.DefaultAvatarChangesPerHour) + " changes/hour. Clear restores the initial."

var guideReactions = func() string {
	defaults := make([]string, len(envelope.ReactionEmoji))
	for i, emoji := range envelope.ReactionEmoji {
		defaults[i] = emoji + " " + envelope.ReactionName(emoji) + ": " + envelope.DefaultReactionPriority(emoji)
	}
	return "Reactions: emoji is one of " + envelope.ReactionList() + "; at most 32 UTF-8 bytes. op defaults to add; remove does not notify. Omitted priority defaults: " + strings.Join(defaults, ", ") + ". A non-operator may wake the target sender once per emoji per target message, ever; removing/re-adding does not reset that limit. Reactions cannot be replied to."
}()
